function calculateCoffeeBreakeven() {
  const machinePrice = parseFloat(document.getElementById('machinePrice').value) || 0;
  const currentCupCost = parseFloat(document.getElementById('currentCupCost').value) || 0;
  const cupsPerDay = parseFloat(document.getElementById('cupsPerDay').value) || 1;
  const beanPricePerKg = parseFloat(document.getElementById('beanPricePerKg').value) || 0;

  // 1杯あたり10g使用、水道光熱費・洗浄コスト約5円
  const homeCupCost = Math.round((beanPricePerKg / 1000 * 10) + 5);
  const savingsPerCup = currentCupCost - homeCupCost;

  const resultEl = document.getElementById('calcResult');

  if (savingsPerCup <= 0) {
    resultEl.innerHTML = `
      <div class="result-headline">結論：<strong>自宅淹れの方が割高です</strong></div>
      <p style="margin-top:8px;color:#c53030;">豆のグレードを下げるか、比較対象の支出設定を見直してください。</p>
    `;
    return;
  }

  const breakevenCups = Math.ceil(machinePrice / savingsPerCup);
  const breakevenDays = Math.ceil(breakevenCups / cupsPerDay);
  const breakevenMonths = (breakevenDays / 30.4).toFixed(1);

  const annualCurrentExpense = currentCupCost * cupsPerDay * 365;
  const annualHomeExpense = homeCupCost * cupsPerDay * 365;
  const annualSavings = annualCurrentExpense - annualHomeExpense;

  resultEl.innerHTML = `
    <div class="result-headline">結論：<strong>約 ${breakevenDays} 日（約 ${breakevenMonths} ヶ月 / ${breakevenCups} 杯）</strong>で元が取れます</div>
    <div class="metrics-row">
      <div class="metric-card">
        <span>自宅コーヒー1杯原価</span>
        <strong>${homeCupCost.toLocaleString()} 円</strong>
        <small>豆10g＋光熱費5円換算</small>
      </div>
      <div class="metric-card">
        <span>1杯あたりの節約差額</span>
        <strong>${savingsPerCup.toLocaleString()} 円</strong>
        <small>普段の支出との差額</small>
      </div>
      <div class="metric-card">
        <span>年間のカフェ代削減効果</span>
        <strong>${annualSavings.toLocaleString()} 円</strong>
        <small>本体代回収後の純節約額</small>
      </div>
    </div>
  `;
}

document.addEventListener('DOMContentLoaded', calculateCoffeeBreakeven);
